@classmethod
def capture(cls, snapshot: RegistrySnapshot, catalog: CatalogDocument, reads: ReadLedger, document: ReadDocument, viewer: str | None) -> DisplaySelection:
    canonical = snapshot.canonical_name(viewer) if viewer is not None else None
    seen = reads.seen_sequences(viewer, snapshot, document=document) if viewer is not None else frozenset()
    return cls(snapshot, catalog, canonical, seen, document)

@classmethod
def capture(cls, thread: Thread, snapshot: RegistrySnapshot, activity: ObservedActivity, runtime: AgentRuntimeInfo | None, waits: dict[str, GoalWait]) -> ThreadView:
    """Roster and individual readers join the same captured authorities."""
    return cls(thread, snapshot.statuses[thread.name], activity, runtime, snapshot.seen_at(thread.name), GoalWaits.execution(thread.goal, waits, snapshot), snapshot.owner_binding(thread.name))

@classmethod
def wire_kind(cls) -> str:
    """The Pi ``type`` this member converts."""
    return cls.declared_name

@classmethod
def normalize_field(cls, target, key, value, record):
    if key == 'message' and target is PiMessage and (value is None):
        return {'kind': AbsentMessage.declared_name}
    if key == 'reason' and target == type[CompactionReason]:
        return FieldCodec.encode(CompactionReason.from_external(value))
    if target is PiToolResult:
        return PiToolResult.normalize_wire(value)
    if target is ProviderRetryOutcome:
        return ProviderRetryOutcome.normalize_wire(record)
    return super().normalize_field(target, key, value, record)

@classmethod
