async def pass_on_unread(self, turns: TurnRunner) -> None:
    """Inputs the ended turn never read start the next turn or are refused, never replayed."""
    while not self.inbox.empty():
        for carried in self.inbox.get_nowait().carried_inputs:
            if await self.pass_on(turns, carried.value):
                return

def __init__(self, store_path: Path):
    self.store = RegistryStore(store_path)
    self.store.read()

def _declare_unlocked(self, thread: Thread, status: ThreadStatus=_RUNNING_STATUS) -> Thread:
    """Cross-store callers already holding wire use the same registry transaction."""
    with self.store.editing() as edit:
        return self._declare_in(edit, thread, status)

def _claim_unlocked(self, thread: Thread) -> Thread:
    """The wire caller holds inbox authority; namespace allocation stays registry-owned."""
    with self.store.editing() as edit:
        requested = thread.for_claim(edit.document.claim_name(thread.name))
        return self._declare_in(edit, requested, RunningThreadStatus())

@staticmethod
def _prepare_declaration(document, channels, thread: Thread, status: ThreadStatus):
    """Derive one declaration after checking its complete namespace."""
    change = document.prepare_declaration(thread, status)
    for tag in change.thread.tags - channels.all_tags(document.threads):
        channels.require_available_tag_name(tag, document.threads)
    return change

def _commit_registration(self, edit: RegistryEdit, change: RegistrationChange) -> None:
    if change.needs_maintenance_admission:
        MaintenanceBarrier(self.store.path).assert_open_unlocked()
    before = change.prior_goal
    history = None
    intent = None
    if before != change.thread.goal:
        history = GoalHistoryStore(self.store.path)
        intent = history.begin(change.thread.created_at, before, change.thread.goal)
    change.apply(edit.document)
    edit.commit()
    if history is not None and intent is not None:
        history.commit(intent)

def live_owner_with_admission(self, name: str) -> tuple[Thread, int]:
    """Read the durable process admission, independent of metadata revisions."""
    with self.store.reading() as document:
        owner = RegistryOwner.capture_local(document.snapshot(), name)
        return (owner.thread, owner.admission_generation)

def _assert_maintenance_open_unlocked(self) -> None:
    from .maintenance_barrier import MaintenanceBarrier
    MaintenanceBarrier(self.store.path).assert_open_unlocked()

def canonical_name(self, name: str) -> str:
    with self.store.reading() as document:
        return document.canonical_name(name)

def goal_history(self, name: str, *, goal_id: str | None=None) -> tuple[GoalHistoryEntry, ...]:
    """Read this owner's recorded transitions, reconciling crash cuts first."""
    with self.store.locked():
        document = self.store._read_unlocked()
        thread = document.require(name)
        return GoalHistoryStore(self.store.path).history(thread.created_at, thread.goal, goal_id=goal_id)

def last_seen(self, name: str) -> float:
    with self.store.reading() as document:
        return document.seen_at(name)

def require(self, name: str) -> Thread:
    with self.store.reading() as document:
        return document.require(name)

def status(self, name: str) -> ThreadStatus:
    with self.store.reading() as document:
        return document.status(name)

def all_threads(self) -> Mapping[str, Thread]:
    with self.store.reading() as document:
        return dict(document.threads)

def entry(self, name: str) -> RegistryEntryRevision:
    """This thread's registry entry and the revision it was read from.

        Other threads' declarations are not decoded.
        """
    return self.store.read_entry(name)

def snapshot(self) -> RegistrySnapshot:
    """Read related declarations and statuses from exactly one store revision."""
    with self.store.reading() as document:
        return document.snapshot()

def active_threads(self) -> Mapping[str, Thread]:
    with self.store.reading() as document:
        return {name: t for name, t in document.threads.items() if document.statuses[name].active}

@classmethod
def of(cls, thread: Thread) -> Self:
    return cls(thread.require_saved_session())

@property
def available(self) -> bool:
    return self.custody.available

def retain(self, child: PiSessionChild, identity: NativeSessionIdentity) -> bool:
    from .native_custody import RetainedNative
    from .session_revision import SessionRevision, SessionRevisionUnavailable
    if not child.proc.alive():
        return False
    try:
        revision = SessionRevision.observe(identity.session_file).require_available()
    except SessionRevisionUnavailable:
        return False
    self.custody = RetainedNative(child, identity, revision)
    return True

@classmethod
def for_worker(cls, runner: Any, session_id: str) -> Self:
    return cls(runner.agent_bin, runner.agent_args, runner.comms, partial(runner.observe_selected_preparation, session_id))

async def prepare(self, thread: Thread, *, open_native=None) -> StateData:
    """Launch (or reuse) and attest the idle child for ``thread``'s saved session."""
    from .coordinator import Coordination
    from .native_session_prepare import NativeSessionPreparation
    if thread.session_file is None:
        raise ValueError('Native preparation requires a saved session')
    if open_native is None:
        open_native = NativeSessionPreparation.open
    environment = await Coordination.run_worker(lambda: thread.native_environment(self.comms.root, self.comms.registry.snapshot(), thread.worktree))
    return await open_native(self, self.agent_bin, self.arguments(thread), worktree=thread.worktree, environment=environment, session_file=thread.session_file, observe=partial(self.observe, thread))

async def inspect(self, thread: Thread, request):
    """Answer one Pi query on the idle child, preparing it first when needed."""
    return await self.custody.inspect(self, partial(self.prepare, thread), request)

async def context_usage(self, thread: Thread) -> ContextUsage:
    from .pi_commands import GetSessionStats
    stats = await self.inspect(thread, GetSessionStats())
    usage = stats.context_usage
    if usage is None:
        return ContextUsage(tokens=None, window=None)
    return ContextUsage(tokens=usage.tokens, window=usage.context_window)

async def compact(self, thread: Thread, instructions: str | None) -> CompactionOutcome:
    """Ask Pi's own engine to compact through its ``compact`` RPC."""
    from .native_pi import NativePiUnavailable
    from .pi_commands import Compact
    try:
        data = await self.inspect(thread, Compact(custom_instructions=instructions))
    except (NativePiUnavailable, ValueError) as error:
        return FailedCompaction(str(error))
    if data.summary is None:
        return NothingToCompaction()
    return PlacedCompaction(summary=data.summary, first_kept=data.first_kept_entry_id, tokens_before=data.tokens_before)

@staticmethod
def read_entries(path: Path, before: EntryRef | None, limit: int) -> EntryPage:
    from .native_transcript import NativeTranscript
    if limit <= 0:
        raise ValueError('A history page needs a positive limit')
    start = path.stat().st_size if before is None else before.order
    page: list[TranscriptEntry] = []
    for record in NativeTranscript(path).reverse(start):
        if record.entry is None:
            continue
        entry = record.entry
        page.append(TranscriptEntry(ref=EntryRef(record.start, entry.source_coordinates.id or ''), kind=entry.transcript_kind(), text=entry.transcript_text(), at=entry.recorded_at))
        if len(page) == limit:
            break
    older = page[-1].ref if len(page) == limit and page[-1].ref.order > 0 else None
    return EntryPage(tuple(page), older)

@classmethod
async def fork(cls, parent: Thread, launcher: str, runtime: LaunchRuntime) -> PiSessionFile:
    """Copy the parent's whole saved history with Pi's own session manager."""
    from .coordinator import Coordination
    from .native_fork import RuntimeForkHelper, RuntimeForkRequest
    package = await Coordination.run_worker(partial(NativePiRpcLaunch.package_for_command, launcher, runtime))
    identity = await RuntimeForkHelper.run(RuntimeForkRequest(str(package), parent.require_saved_session(), parent.worktree, runtime=runtime), cwd=Path(parent.worktree))
    return PiSessionFile(identity.session_file)

async def configure(self, thread: Thread, model: str | None, thinking: str | None) -> tuple[str, str]:
    from .native_pi import NativePiUnavailable
    from .pi_commands import SetModel, SetThinkingLevel
    from .pi_vocabulary import ThinkingLevel
    commands = []
    if model is not None:
        provider, model_id = model.split('/', 1)
        commands.append(SetModel(provider=provider, model_id=model_id))
    if thinking is not None:
        commands.append(SetThinkingLevel(level=thinking))
    if not commands:
        raise ValueError('A configuration change names a model or a thinking level')
    arguments = self.arguments(thread)
    for command in commands:
        state = await command.configure(self.agent_bin, arguments, worktree=Path(thread.worktree))
        arguments = self.agent_args.with_model(state.model.display_name).with_thinking(ThinkingLevel.optional_name(state.thinking_level)).argv
    selected, level = (state.model.display_name, ThinkingLevel.optional_name(state.thinking_level))
    if selected is None or level is None:
        raise NativePiUnavailable('Native configuration did not report model and thinking level')
    return (selected, level)

