def reserve(self, request: DisclosureRequest, grant) -> AnnotationRequestsRow:
    key = self.address(request.span, request.question, request.classifier)
    with self.session.transaction() as db:
        if AnnotationRequestsRow.one(db, **key) is not None:
            raise PreviouslyRequestedAnnotation('Original classifier request already recorded; inspect its disposition')
        now = self.session.now()
        grant.require_budget(AnnotationRequestsRow.requests_since(db, request.grant, grant.window_start(now)))
        original = AnnotationRequestsRow(request=request, outcome=SubmittedAnnotationOutcome(), created_at_ms=now)
        sequence = original.insert(db).lastrowid
        return AnnotationRequestsRow.one(db, id=sequence)

def send(self, sender: str, target: str, body: str, type: Type[MessageKind]=InfoKind, *, notice: bool=False, claims: Sequence[FileClaimPath]=(), releases: Sequence[str | Path]=(), report: ChangeReport | None=None) -> str:
    """Declare a message and route it through the bus."""
    return self.send_message(sender, target, body, type, notice=notice, claims=claims, releases=releases, report=report).message_id

@staticmethod
def reserve(*, owner, comms, autonomous):
    try:
        store = comms.goals.open_goal_store()
        admission = comms.registry.snapshot().admission_generations[owner.name]
        with _store_lock(comms._wire_lock_path):
            generation = store.require_generation(owner.goal.id)
            generation.lifecycle.require_ready()
            grant = comms.goals.ready_goal_grant_locked(owner, admission, generation)
            reservation = store.reserve(owner.goal.id, generation.number, ready_grant=grant)
            return store.claim_launch(reservation)
    except GoalAttemptError as error:
        if autonomous:
            return None
        raise RequestError.invalid_params({'reason': 'goal_attempt_unavailable', 'details': 'The goal has no launchable attempt. Inspect its state and use Retry for a failed attempt; no prompt was sent to Pi.'}) from error

def take(self, result_type: type, request_id: str, value: Any) -> Any:
    """Resolve a transport result and return its originating command, once."""
    pending = self._pending.pop((result_type, request_id), None)
    if pending is None:
        return None
    if not pending.future.done():
        pending.future.set_result(value)
    return pending.request

def cancel_all(self) -> None:
    for pending in self._pending.values():
        pending.future.cancel()
    self._pending.clear()

def take_anonymous(self, result_type: type, value: Any) -> Any:
    for (owner, identity), pending in self._pending.items():
        if owner is result_type and pending.request.id is None:
            return self.take(owner, identity, value)
    return None

def source(self, public_id: str | None) -> TurnInputSource:
    if public_id is None:
        return self.original
    source = self.inputs.following_sources.get(self.session_id, {}).get(public_id)
    return source if source is not None else RoutedFollowingInput(keys=(), accepted_id=public_id, goal_permission=self.original.goal_permission)

def _check_owner(self, current: Thread | None, snapshot: RegistrySnapshot, canonical: str, source: TurnInputSource, text: str) -> None:
    if current is None:
        MissingTurnOwnerCheck().require_valid()
    OrdinaryOwnerCheck(expected=self.thread, current=current, registry=snapshot, canonical=canonical, admission=self.admission, turn=self.turn).require_valid()
    InputKeysCheck(source=source, text=text).require_valid()
    if source.accepted_id is None:
        return
    accepted = self.inputs.queued_inputs.get(self.session_id, {}).get(source.accepted_id)
    if accepted is None:
        for row in self.inputs.dispositions.read(source.keys).rows.values():
            row.require_not_cleared()
        MissingAcceptedInputCheck().require_valid()
    AcceptedInputCheck(receipt=accepted, current=current, admission=self.admission, input_id=source.accepted_id, keys=source.keys, accepted_source=self.inputs.following_sources.get(self.session_id, {}).get(source.accepted_id)).require_valid()

def _require_context(self, source: TurnInputSource, current: Thread, wait: GoalWait) -> None:
    OrdinaryContextCheck(source=source, owner=current, goal=current.goal, wait=wait, comms=self.comms).require_valid()
    if not source.bypasses_goal_permit and self.goal_permit is not None:
        OrdinaryGoalGrantCheck(permit=self.goal_permit, store=self.goal_store).require_valid()

def _refusal(self, rule: ReservationRule, defer: bool) -> bool | None:
    _LOG.info('Ordinary input %s: %s', 'deferred' if defer else 'refused', ReservationViolationError(rule))
    return None if defer else False

def _prepare(self, public_id: str | None, native_id: str, sent_text: str, *, already_bound: bool=False) -> bool | None:
    snapshot = self.comms.registry.snapshot()
    canonical = snapshot.canonical_name(self.thread.name)
    current = snapshot.threads.get(canonical)
    source = self.source(public_id)
    try:
        self._check_owner(current, snapshot, canonical, source, sent_text)
    except ReservationViolationError as error:
        return self._refusal(error.rule, False)
    wait = self.comms.goals.goal_wait(canonical)
    defer = source.defers_for_goal(self.thread.goal, current.goal)
    try:
        self._require_context(source, current, wait)
    except ReservationViolationError as error:
        return self._refusal(error.rule, defer)
    if not self.inputs.dispositions.bind_turn_input(source.keys, admission=self.admission, turn_id=self.turn.value, native_id=native_id, text=sent_text, already_bound=already_bound):
        return self._refusal(UnboundOrdinaryInputRule(), defer)
    if not source.consume_wait(self.comms, canonical, wait):
        return self._refusal(UnconsumedDependencyRule(), defer)
    self.comms.transcripts.routes.record_input_display(native_id, source.display(self.inputs.dispositions, sent_text), sent_text=sent_text, routing=TurnRouting(tuple((origin.reference for origin in source.origins)), None) if source.origins else None)
    return True

@contextmanager
def __call__(self, public_id: str | None, native_id: str, sent_text: str, *, already_bound: bool=False) -> Iterator[bool | None]:
    try:
        decision = self._prepare(public_id, native_id, sent_text, already_bound=already_bound)
    except InputAlreadyCleared:
        decision = None
    yield decision

def native_start(self, public_id: str | None, native_id: str, sent_text: str) -> bool:
    source = self.source(public_id)
    return source.valid_keys(sent_text) and all((self.inputs.dispositions.started(key, turn_id=self.turn.value, native_id=native_id, text=sent_text) for key in source.keys))

def append(self, delta: str) -> None:
    self._text.append(delta)
    self._message.append(delta)

def record_failure(self, failure: failures.TurnFailure) -> None:
    if failure.supersedes(self.failure):
        self.failure = failure

def request_retried(self) -> None:
    """Pi re-sends the refused request; that refusal no longer decides the turn."""
    if self.failure is not None and self.failure.ends_with_request_retry:
        self.failure = None
    self.error_message = None

def raise_if_failed(self, proof, provider: str, model: str) -> None:
    if self.failure is not None:
        self.declared_failure.raise_native(proof, provider, model)

@property
def declared_failure(self) -> failures.TurnFailure:
    failure = self.failure
    if failure is None:
        raise ValueError('Failed native terminal lacks its declared failure')
    if self.retry_result is None:
        return failure
    return self.retry_result.refine_failure(failure)

@property
def failure_text(self) -> str:
    return self.failure.text if self.failure else ''

@property
def clean(self) -> bool:
    return self.failure is None and self.error_message is None

def error(self, text: str, diagnostics: tuple[PiDiagnostic, ...]=(), source: FailureSource=UnrecordedFailureSource()) -> events.Error:
    self.error_message = self.redact(text)
    return events.Error(text=self.error_message, diagnostics=() if self.sensitive else diagnostics, source=source.for_publication(self.error_message, self.sensitive))

def startup_error(self, stderr: str) -> None:
    if self.failure and stderr.strip() and (not self.sensitive):
        self.failure = self.failure.with_startup_diagnostics(stderr.strip())

def settle(self, session: TurnSession, transport_ok: bool) -> None:
    for cause in sorted(failures.TurnFailure.members_with(failures.TerminalFailure), key=lambda member: member.precedence, reverse=True):
        if cause.detected(session, transport_ok):
            self.record_failure(cause(cause.explanation(self)))

def permits_retention(self, session: TurnSession) -> bool:
    self.settle(session, transport_ok=True)
    return self.clean

def terminal_text(self, success: bool, stderr: str, returncode: int | None) -> str:
    if self.failure is not None:
        return self.failure.text
    if success:
        return ''.join(self._text).strip()
    return self.error_message or (self.redact(stderr) if stderr else '') or f'Backend exited with code {returncode}'

