@staticmethod
async def observations(*sources: WatchSource) -> AsyncIterator[WireWatch]:
    watcher = open_wire_watcher(*sources)
    try:
        while True:
            await watcher.prepare()
            yield watcher
            watcher = await watcher.wait()
    finally:
        watcher.close()

async def wait(self) -> WireWatch:
    if self.invalid:
        self.close()
        return open_wire_watcher(*self.sources)
    await self.changed.wait()
    return self

def _schedule_changed(self) -> None:
    if self._pending_change is None:
        self._pending_change = self.loop.call_later(self.event_settle_seconds, self._publish_changed)

def _publish_changed(self) -> None:
    self._pending_change = None
    self.changed.set()

def _on_ready(self) -> None:
    try:
        while (raw := os.read(self.fd, 65536)):
            offset = 0
            while offset + _HEADER.size <= len(raw):
                watch, mask, _, length = _HEADER.unpack_from(raw, offset)
                offset += _HEADER.size
                name = raw[offset:offset + length].partition(b'\x00')[0]
                offset += length
                directory = self.directories.get(watch)
                if directory is not None and directory.includes(name) or mask & (_IN_Q_OVERFLOW | _IN_IGNORED | _IN_DELETE_SELF | _IN_MOVE_SELF):
                    self._schedule_changed()
                if directory is not None and name in directory.reopen or mask & (_IN_IGNORED | _IN_DELETE_SELF | _IN_MOVE_SELF):
                    self.invalid = True
    except BlockingIOError:
        pass
    except OSError:
        self.invalid = True
        self.changed.set()

def close(self) -> None:
    if self._pending_change is not None:
        self._pending_change.cancel()
        self._pending_change = None
    if self.fd >= 0:
        self.loop.remove_reader(self.fd)
        os.close(self.fd)
        self.fd = -1

def open_wire_watcher(*sources: WatchSource) -> WireWatch:
    """Use Linux notifications for every declared physical change source.

    A healthy native watcher reports queue loss and watched-directory removal,
    so it needs no periodic speculative read. Platforms or source directories
    without native notification use the existing polling owner.
    """
    if not sources:
        raise ValueError('Wire watcher requires at least one source')
    if sys.platform != 'linux':
        return PollingWireWatch()
    libc = ctypes.CDLL(None, use_errno=True)
    init = libc.inotify_init1
    add = libc.inotify_add_watch
    init.argtypes = [ctypes.c_int]
    init.restype = ctypes.c_int
    add.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_uint32]
    add.restype = ctypes.c_int
    fd = init(os.O_NONBLOCK | os.O_CLOEXEC)
    if fd < 0:
        raise OSError(ctypes.get_errno(), 'inotify_init1 failed')
    grouped: dict[Path, WatchedDirectory] = {}
    for source in sources:
        directory = source.directory
        observed, reopen = (source, frozenset())
        while not directory.is_dir() and directory != directory.parent:
            reopen = frozenset({os.fsencode(directory.name)})
            directory = directory.parent
            observed = ReplacedWatchSource(directory, reopen)
        current = grouped.get(directory, WatchedDirectory((), False, frozenset()))
        grouped[directory] = WatchedDirectory((*current.sources, observed), current.modified or (source.modified and (not reopen)), current.reopen | reopen)
    directories = {}
    for directory, watched in grouped.items():
        watch = add(fd, os.fsencode(directory), _MASK | (_IN_MODIFY if watched.modified else 0) | (_IN_CREATE if watched.reopen else 0))
        if watch < 0:
            error = OSError(ctypes.get_errno(), f'inotify_add_watch failed for {directory}')
            os.close(fd)
            raise error
        directories[watch] = watched
    try:
        return WireChangeWatch(fd, asyncio.get_running_loop(), tuple(sources), directories)
    except (NotImplementedError, OSError):
        os.close(fd)
        raise

def _enter_admission(fd: int, boundary: Callable[[], AbstractContextManager[None]], cancelled: threading.Event, measurements: PublicationMeasurements) -> ExitStack:
    """Acquire cancellable admission without spending an irreversible-write budget.

    Every refused probe closes its partial custody. Only the successful original
    boundary can admit this payload; cancellation here proves no prompt write.
    """
    busy: PromptAdmissionBusy | None = None
    pipe = select.poll()
    pipe.register(fd, select.POLLERR | select.POLLHUP | select.POLLNVAL)
    while True:
        if cancelled.is_set():
            raise PromptSendNotWritten('Native prompt admission cancelled before writing any bytes') from busy
        if pipe.poll(0):
            raise PromptSendNotWritten('Native pipe closed before prompt admission')
        scope = ExitStack()
        try:
            with measurements.operation('admission_probe'):
                scope.enter_context(boundary())
        except PromptAdmissionBusy as error:
            busy = error
            scope.close()
            cancelled.wait(0.01)
        except BaseException:
            scope.close()
            raise
        else:
            return scope

def _write_fenced(fd: int, payload: bytes, boundary: Callable[[], AbstractContextManager[None]], cancelled: threading.Event, timeout: float, measurements: PublicationMeasurements) -> None:
    written = 0
    try:
        with measurements.operation('admission_wait'):
            admitted = _enter_admission(fd, boundary, cancelled, measurements)
        with admitted:
            deadline = time.monotonic() + timeout
            remaining = memoryview(payload)
            while remaining:
                budget = deadline - time.monotonic()
                if cancelled.is_set() or budget <= 0:
                    raise PromptSendUnknown('Native prompt send is UNKNOWN after cancellation/deadline')
                try:
                    with measurements.operation('raw_pipe_write'):
                        count = os.write(fd, remaining)
                except BlockingIOError:
                    select.select([], [fd], [], min(budget, 0.05))
                    continue
                except OSError as error:
                    raise PromptSendUnknown('Native prompt write is UNKNOWN; no retry') from error
                if count <= 0:
                    raise PromptSendUnknown('Native prompt short write is UNKNOWN; no retry')
                written += count
                remaining = remaining[count:]
    except Exception as error:
        if written and (not isinstance(error, PromptSendUnknown)):
            raise PromptSendUnknown(f'Native prompt post-write outcome is UNKNOWN; no retry: {type(error).__name__}: {error}') from error
        raise

async def send_fenced_prompt(stdin: asyncio.StreamWriter, payload: bytes, boundary: Callable[[], AbstractContextManager[None]], *, measurements: PublicationMeasurements, timeout: float=_MAX_SEND_SECONDS) -> None:
    """Own a duplicated nonblocking pipe fd until the writer has stopped.

    Cancellation is signalled to the independent writer and joined before this
    function exits. A dedicated thread avoids default-executor queue starvation.
    Each admission probe is nonblocking and uses thread-local database connections.
    Contention waits for original admission without retaining partial locks or
    depending on owner-loop callbacks. The write budget begins only after grant.
    Cancellation or a closed original pipe before grant proves no bytes. No
    admitted send is retried.
    """
    if os.name != 'posix' or not payload or timeout <= 0:
        raise PromptSendNotWritten('Fenced prompt requires a live bounded POSIX pipe')
    pipe = stdin.get_extra_info('pipe')
    transport = stdin.transport
    if pipe is None or transport.get_write_buffer_size() != 0:
        raise PromptSendNotWritten('Native stdin is not an empty raw pipe; no prompt sent')
    fd = os.dup(pipe.fileno())
    if os.get_blocking(fd):
        os.close(fd)
        raise PromptSendNotWritten('Native stdin must be nonblocking; no prompt sent')
    loop = asyncio.get_running_loop()
    done: asyncio.Future[None] = loop.create_future()
    cancelled = threading.Event()
    write_timeout = min(timeout, _MAX_SEND_SECONDS)

    def finish(error: BaseException | None) -> None:
        writer.join()
        if error is None:
            done.set_result(None)
        else:
            done.set_exception(error)

    def worker() -> None:
        error: BaseException | None = None
        try:
            _write_fenced(fd, payload, boundary, cancelled, write_timeout, measurements)
        except BaseException as caught:
            error = caught
        finally:
            try:
                os.close(fd)
            except OSError as caught:
                if error is None:
                    error = caught
                else:
                    error.add_note(f'Closing the native prompt fd also failed: {caught!r}')
        loop.call_soon_threadsafe(finish, error)
    writer = threading.Thread(target=worker, name='native-prompt-writer', daemon=False)
    try:
        writer.start()
    except BaseException:
        os.close(fd)
        raise
    try:
        await asyncio.shield(done)
    except asyncio.CancelledError as cancellation:
        cancelled.set()
        while not done.done():
            try:
                await asyncio.shield(done)
            except asyncio.CancelledError:
                cancelled.set()
            except Exception:
                break
        if not done.cancelled() and (outcome := done.exception()) is not None:
            cancellation.__cause__ = outcome
        raise

def finish(error: BaseException | None) -> None:
    writer.join()
    if error is None:
        done.set_result(None)
    else:
        done.set_exception(error)

def worker() -> None:
    error: BaseException | None = None
    try:
        _write_fenced(fd, payload, boundary, cancelled, write_timeout, measurements)
    except BaseException as caught:
        error = caught
    finally:
        try:
            os.close(fd)
        except OSError as caught:
            if error is None:
                error = caught
            else:
                error.add_note(f'Closing the native prompt fd also failed: {caught!r}')
    loop.call_soon_threadsafe(finish, error)

@classmethod
def capture(cls, document: RegistryDocument) -> RegistrySnapshot:
    """One live registry cut owns the index and all its source maps."""
    indexed: dict[str, Thread] = {}
    for thread in document.threads.values():
        incarnation = thread.incarnation.require_recorded()
        lookup = incarnation.lookup
        indexed[lookup] = thread
    return cls(threads=MappingProxyType(dict(document.threads)), statuses=MappingProxyType(dict(document.statuses)), last_seen=MappingProxyType(dict(document.last_seen)), aliases=MappingProxyType(dict(document.aliases)), owner_generations=MappingProxyType(dict(document.owners.generations)), admission_generations=MappingProxyType(dict(document.admissions.generations)), by_lookup=MappingProxyType(indexed))

def _release_abandoned(task: asyncio.Future[ExitStack]) -> None:
    if not task.cancelled() and task.exception() is None:
        task.result().close()

def _registries(self) -> list[Path]:
    roots = {self.selection.root}
    if self.attached is not None:
        attached = Path(self.attached).expanduser()
        roots.add(attached if attached.is_absolute() else self.cwd / attached)
    return sorted({root.resolve() / 'registry.json' for root in roots})

def _admit(self, custody: ExitStack) -> None:
    """Share open-root wire custody; maintenance takes it exclusively."""
    for registry in self._registries():
        custody.enter_context(MaintenanceBarrier(registry).admit_ingress())

def _admit_prompt(self, custody: ExitStack) -> None:
    custody.enter_context(selected_write(self.selection.root, implicit=self.selection.implicit))
    self._admit(custody)

@staticmethod
async def _acquire(admit) -> ExitStack:
    """Acquire custody in a worker; a cancelled waiter never leaks it."""

    def acquire() -> ExitStack:
        with ExitStack() as custody:
            admit(custody)
            return custody.pop_all()
    task = asyncio.ensure_future(asyncio.to_thread(acquire))
    try:
        return await asyncio.shield(task)
    except asyncio.CancelledError:
        task.add_done_callback(_release_abandoned)
        raise

def acquire() -> ExitStack:
    with ExitStack() as custody:
        admit(custody)
        return custody.pop_all()

def _project_launch(self, child_env: dict[str, str]) -> None:
    """Publish the captured root into the child only after locked admission."""
    from .active_route import read_active_route
    from .private_nk_entrypoint import PrivateNkLaunch
    from .launch_runtime import PACKAGE_ENV, ROOT_ID_ENV
    root = self.selection.root
    child_env['AGENT_COMMS_ROOT'] = str(root)
    if self.selection.implicit:
        route = read_active_route()
        if route is None:
            return
        if route != self.selection.route:
            raise ValueError('ACP root changed before private launch')
        for key, expected in ((ROOT_ID_ENV, route.wire_root_id), (PACKAGE_ENV, str(route.native_package))):
            if key in child_env and child_env[key] != expected:
                raise ValueError('ACP private launch identity conflicts with route')
            child_env[key] = expected
    elif ROOT_ID_ENV in child_env or PACKAGE_ENV in child_env:
        launch = PrivateNkLaunch.from_environment(root, child_env)
        if launch is None:
            raise ValueError('ACP private launch selection is absent')
        launch.validate()

async def spawn(self, argv: tuple[str, ...], *, env: Mapping[str, str], pass_fds: tuple[int, ...]=(), stdio: ChildStdio=StreamingChildStdio()) -> AttachedChild:
    """Hold route and wire admission until the asynchronous spawn settles.

        A worker owns the synchronous admission while the subprocess starts on
        the caller's loop. A cancelled caller still waits for the exact spawn
        and retires its child; the gate is never dropped while an unobserved
        spawn can complete later. A permanently stuck OS spawn can prevent a
        maintenance pause from completing; there is no bounded deadline.
        """
    loop = asyncio.get_running_loop()
    child_env = dict(env)
    cwd = str(self.cwd)
    process_ready: concurrent.futures.Future[AttachedChild] = concurrent.futures.Future()
    decision: concurrent.futures.Future[bool] = concurrent.futures.Future()

    async def settle(task: asyncio.Future) -> tuple[object, bool]:
        """Repeated caller cancellation cannot abandon a lock-held spawn."""
        cancelled = False
        while True:
            try:
                return (await asyncio.shield(task), cancelled)
            except asyncio.CancelledError:
                cancelled = True

    def spawn_under_lock() -> None:
        try:
            if child_root(child_env, cwd) != self.selection.root:
                raise ValueError('ACP child environment conflicts with its selected route')
            with self.selection.route.admit_client(), ExitStack() as admission:
                self._admit(admission)
                self._project_launch(child_env)
                process = asyncio.run_coroutine_threadsafe(AttachedChild.start(argv, env=child_env, cwd=cwd, pass_fds=pass_fds, stdio=stdio), loop).result()
                process_ready.set_result(process)
                if not decision.result():
                    while True:
                        try:
                            asyncio.run_coroutine_threadsafe(process.stop(), loop).result()
                        except Exception:
                            time.sleep(0.1)
                            continue
                        break
        except BaseException as error:
            if not process_ready.done():
                process_ready.set_exception(error)
            else:
                raise
    worker = asyncio.ensure_future(asyncio.to_thread(spawn_under_lock))
    try:
        process, cancelled = await settle(asyncio.wrap_future(process_ready))
    except BaseException:
        await settle(worker)
        raise
    if cancelled:
        decision.set_result(False)
        await settle(worker)
        raise asyncio.CancelledError
    decision.set_result(True)
    return process

async def settle(task: asyncio.Future) -> tuple[object, bool]:
    """Repeated caller cancellation cannot abandon a lock-held spawn."""
    cancelled = False
    while True:
        try:
            return (await asyncio.shield(task), cancelled)
        except asyncio.CancelledError:
            cancelled = True

def spawn_under_lock() -> None:
    try:
        if child_root(child_env, cwd) != self.selection.root:
            raise ValueError('ACP child environment conflicts with its selected route')
        with self.selection.route.admit_client(), ExitStack() as admission:
            self._admit(admission)
            self._project_launch(child_env)
            process = asyncio.run_coroutine_threadsafe(AttachedChild.start(argv, env=child_env, cwd=cwd, pass_fds=pass_fds, stdio=stdio), loop).result()
            process_ready.set_result(process)
            if not decision.result():
                while True:
                    try:
                        asyncio.run_coroutine_threadsafe(process.stop(), loop).result()
                    except Exception:
                        time.sleep(0.1)
                        continue
                    break
    except BaseException as error:
        if not process_ready.done():
            process_ready.set_exception(error)
        else:
            raise

