@classmethod
async def execute(cls, package: Path, *, input_id: str, prompt: str, context_contributions: tuple[InputContributionCoordinates, ...]=(), worktree: Path, session: SelectedSession, provider: str, model: str, thinking_level: str | None=None, environment: dict[str, str] | None=None, model_wait_timeout: float | None=MODEL_WAIT_TIMEOUT_SECONDS, prompt_send_boundary: PrivateSendAdmission | None=None, maintenance_root: Path | None=None, selected_tool_mode: NativeToolMode | None=None, observe_event: Callable[[pi.PiEvent | AgentEvent | ObservedAttestation], Awaitable[None]] | None=None, acquisition_measurements: PublicationMeasurements | None=None, request_observer: Callable[[RequestProgress, ProcessIdentity], None] | None=None, launch_owner: SelectedExecution | None=None, pi_session: PersistentPiSession | None=None, following: FollowingInputs=FollowingInputs()) -> NativeTurnResult:
    if type(input_id) is not str or re.fullmatch('[0-9a-f]{32}', input_id) is None:
        raise ValueError('A native turn requires a 128-bit lowercase hex input ID')
    if not prompt or not isinstance(prompt, str):
        raise ValueError('A native turn requires a nonempty prompt')
    if model_wait_timeout is not None and (not math.isfinite(model_wait_timeout) or model_wait_timeout <= 0):
        raise ValueError('A model progress wait must be positive and finite')
    measurements = acquisition_measurements if acquisition_measurements is not None else PublicationMeasurements()
    with measurements.operation('native_launch_selection'):
        launch = await Coordination.run_worker(partial(NativePiRpcLaunch.tracked if launch_owner is None else launch_owner.tracked_launch, package, worktree=worktree, session=session, provider=provider, model=model, thinking_level=thinking_level, environment=environment, selected_tool_mode=selected_tool_mode))
    turn = cls(launch, commands.Prompt(id='native-prompt', input_id=input_id, message=prompt, context_contributions=context_contributions), provider=provider, model=model, model_wait_timeout=model_wait_timeout, prompt_send_boundary=prompt_send_boundary, maintenance_root=maintenance_root, startup=NativeStartup.for_launch(launch, root=maintenance_root, measurements=measurements), selected_tool_mode=selected_tool_mode, observe_event=observe_event, request_observer=request_observer, pi_session=launch_owner.pi_session if launch_owner is not None else pi_session, following=following)
    return await turn.complete()

@property
def active_tools(self):
    return self.tool_socket.active_tools if self.tool_socket is not None else set()

async def next_event(self) -> pi.PiEvent:
    try:
        while True:
            refused, self.rejected_commands = (self.rejected_commands, [])
            self.rejected_signal.clear()
            for command in refused:
                await self.following.retired(command)
            raw = await self.watchdog.read(self)
            if not self.rejected_commands:
                break
        event = PiRpcChannel.decode_record(raw, strict=True) if raw else None
    except (UnicodeError, ValueError, TypeError) as error:
        raise NativePiUnavailable(f'Native Pi RPC record is invalid or incomplete; {type(error).__name__}: {error}') from error
    if event is None:
        await self.native.shutdown(graceful=True)
        stderr = await self.native.stderr_task
        raise NativePiUnavailable(f"Native Pi RPC record is incomplete; native exit={self.native.proc.returncode}; stderr={stderr or '(empty)'}")
    return event

async def send(self, command: commands.PiCommand) -> None:
    payload = self.native.reader.encode(command)
    if self.maintenance_root is not None:
        try:
            async with MaintenanceBarrier(self.maintenance_root / 'registry.json').admit_ingress_async():
                self.write(command, payload)
        except RelationViolationError as error:
            raise NativePiUnavailable('Maintenance closed before Pi capability preflight') from error
    else:
        self.write(command, payload)
    wait = self.watchdog.wait_for(self)
    with wait.charge(self.watchdog.clock):
        await asyncio.wait_for(self.native.proc.stdin.drain(), timeout=wait.timeout())

def write(self, command: commands.PiCommand, payload: bytes) -> None:
    if command is self.command:
        self.grant_prompt()
    self.native.proc.stdin.write(payload)

@contextmanager
def prompt_boundary(self):
    with self.prompt_send_boundary(self.native.attestation.identity):
        self.grant_prompt()
        yield

async def admit_prompt(self) -> None:
    if self.prompt_send_boundary is None:
        await self.send(self.command)
    else:
        with self.startup.measurements.operation('prompt_writer_join'):
            await send_fenced_prompt(self.native.proc.stdin, self.native.reader.encode(self.command), self.prompt_boundary, measurements=self.startup.measurements)

@property
def prompt_id(self) -> str:
    return self.command.id

@handles(pi.Response)
async def response(self, event: pi.Response) -> None:
    request = self.native.reader.correlate(event)
    if event.id == self.command.id:
        if request is not self.command:
            raise NativePiUnavailable('Native Pi prompt acknowledgement differs')
        if event.success is not True:
            raise NativePiPromptRejected(event)
        self.prompt_state = self.prompt_state.acknowledge(event)
    elif issubclass(event.command, commands.MutatesSession):
        raise NativePiUnavailable('Native Pi session identity changed during a turn')
    else:
        async for update in event.command.on_response(event, self):
            if self.observe_event is not None:
                await self.observe_event(update)

