async def prompt(self, session_id: str, prompt: list[Any], **kwargs: Any) -> PromptResponse:
    from .acp_extension import decode_request
    from .acp_request_consumer import AcpRequestConsumer
    try:
        request = decode_request(kwargs.get('_meta') or kwargs.get('field_meta'), **kwargs)
    except (ValueError, TypeError) as error:
        raise RequestError.invalid_params({'reason': str(error)}) from error
    text = self._prompt_text(prompt).strip()
    if re.match('^/compact(?:\\s|$)', text):
        self._require_compaction_text(prompt)
        request = CompactRequest(text[len('/compact'):].strip())
    return await AcpRequestConsumer(self, session_id, prompt).run(request)

async def _compact_request(self, session_id: str, instructions: str | None) -> PromptResponse:
    from . import manual_compaction_bridge
    from .agent_backend import CompactionOutcome
    if session_id in self.sessions.proxies:
        outcome = FieldCodec.decode(CompactionOutcome, await self.sessions.proxies[session_id].request('compact', instructions=instructions))
    else:
        outcome = await manual_compaction_bridge.compact_context(self.turns, session_id, instructions)
    return manual_compaction_bridge.CompactionReply().reply(outcome)

async def _prompt_request(self, session_id: str, prompt: list[Any], request) -> PromptResponse:
    display_text = request.user_text or self._prompt_text(prompt)
    try:
        images = prompt_images(prompt)
    except ValueError as error:
        raise RequestError.invalid_params({'reason': str(error)}) from error
    if images and self._prompt_text(prompt).lstrip().startswith(('@', '#', RELAY_PREFIX)):
        raise RequestError.invalid_params({'reason': 'Send images to an agent thread, not as a coordination relay.'})
    text = self._prompt_text(prompt)
    if await self.turns.active_backend_inbox(session_id) is not None and (not text.lstrip().startswith(('@', '#', RELAY_PREFIX))):
        return await self.inputs.accept_followup(session_id, text=text, display_text=display_text, request=request, images=images)
    async with self.turns.turn_locks.setdefault(session_id, asyncio.Lock()):
        existing = self._runtime.controller.get()
        context = self._runtime.controller.set(self.sessions.client) if existing is UNBOUND_CONTROLLER else None
        try:
            return await self.turns.prompt_owned(session_id, prompt, display_text=display_text, input_id=request.input_id, origin=request.origin)
        finally:
            if context is not None:
                self._runtime.controller.reset(context)

