    return '\n'.join((chunk for chunk in chunks if chunk))

async def run() -> None:
    if os.environ.get('AGENT_COMMS_DEBUG_LOG'):

        async def watchdog() -> None:
            while True:
                await asyncio.sleep(5)
                tasks = [t for t in asyncio.all_tasks() if not t.done()]
                with open(os.environ['AGENT_COMMS_DEBUG_LOG'], 'a') as debug_log:
                    debug_log.write(f'=== watchdog: {len(tasks)} tasks ===\n')
                    for task in tasks:
                        stack = task.get_stack()
                        innermost = [f"{frame.f_code.co_filename.split('/')[-1]}:{frame.f_lineno}" for frame in stack if frame][-4:]
                        debug_log.write(f"  {task.get_name()}: {' <- '.join(innermost)}\n")
        asyncio.create_task(watchdog())
    agent = CommsClient(comms, runtime_enabled=True, use_unstable_protocol=True, private_nk_native_package=private_nk.native_package if private_nk else None, private_nk_wire_root_id=private_nk.wire_root_id if private_nk else None)

    def observe(event: Any) -> None:
        agent._debug_log(f'{event.direction.value}: {json.dumps(event.message)[:200]}' if hasattr(event, 'message') else f'{event.direction.value}')
    conn_kwargs: dict[str, Any] = {}
    if os.environ.get('AGENT_COMMS_DEBUG_LOG'):
        conn_kwargs['observers'] = [observe]
    try:
        await run_agent(agent, use_unstable_protocol=agent.use_unstable_protocol, **conn_kwargs)
    finally:
        await agent.shutdown()

