    unplaced = tuple((item for item, _content in reserved if placed.get(item.input_id) is not item))
    for item in unplaced:
        await item.not_started(inputs)

@staticmethod
def _recover_locked(comms: Comms, dispositions: InputDispositions, name: str, root_id: str, live_keys: frozenset[str]) -> int:
    """Acquire, recover and release entirely inside the joined worker."""
    entry = comms.registry.entry(name).entry
    owner = entry.thread
    document = dispositions.unresolved(entry.names)
    if not any((row.key not in live_keys for row in document.unbound_wire_inputs(root_id).values())):
        return 0
    with _store_lock(comms._wire_lock_path):
        entry = comms.registry.entry(name).entry
        owner = entry.thread
        document = dispositions.unresolved(entry.names)
        rows = {reference: row for reference, row in document.unbound_wire_inputs(root_id).items() if row.key not in live_keys}
        if not rows:
            return 0
        path = str(comms.root / 'coordination.sqlite3')
        with Coordination(path, session_type=ReadNativeCoordinationSession) as store:
            assignments = store.assignments.recoverable_unbound_deliveries(owner.incarnation.lookup, frozenset(rows))
        if not assignments:
            return 0
        with Coordination(path) as store:
            dispositions.settle_unbound(tuple((rows[row.source].key for row in assignments)))
            restored = 0
            for assignment in assignments:
                try:
                    store.assignments.restore_unbound_delivery(assignment)
                except StaleRevision:
                    continue
                restored += 1
            return restored

def read(store: Coordination):
    with store.session.read():
        assignments = pending_sealed_assignments(store, lookup, owner.name, after_seq=after_seq)
    with bus.log.certified_read() as source:
        if source.marker.root_id != root_id:
            raise IdentityConflict('delivered source wire root changed')
        originals = tuple(source.references(tuple((assignment.source for assignment in assignments))))
    return tuple(zip(originals, assignments, strict=True))

