def ensure_input_forwarding(self):
    if self.inputs.can_forward(self.native.proc.stdin):
        self.stdin = self.native.proc.stdin
        self.native.forward_input(partial(self.inputs.forward, self))

def observe_input_during_abort(self, event):
    if self.accepts_output:
        matched, identity = self.inputs.mark_started(self, event)
        if matched:
            self.started_during_abort.append(identity)

def permits_live_receipt(self) -> bool:
    """Only tracked, live input may publish an informational package receipt."""
    if self.stats.requested:
        return False
    return self.require_input_id and self.prompt_state.permits_extension_ui(self)

async def abort_stalled_rpc(self) -> None:
    await self.native.finish_input()
    if self.native.proc.stdin is not None and self.native.proc.returncode is None:
        abort_deadline = self.loop.time() + max(0.0, self.rpc_abort_grace)
        try:
            self.native.proc.stdin.write(self.native.reader.encode(commands.Abort(id='agent-comms-watchdog')))
            remaining = max(0.0, abort_deadline - self.loop.time())
            await asyncio.wait_for(self.native.proc.stdin.drain(), timeout=remaining)
            while (remaining := max(0.0, abort_deadline - self.loop.time())):
                response = await asyncio.wait_for(self.native.reader.readline(), timeout=remaining)
                if not response:
                    break
                try:
                    abort_payload = PiRpcChannel.decode_record(response)
                except (ValueError, TypeError, UnicodeError):
                    continue
                abort_payload.observe_abort(self)
                if isinstance(abort_payload, pi.Response) and abort_payload.command is commands.Abort:
                    break
        except (TimeoutError, OSError):
            pass
    await self.native.shutdown()

@contextmanager
def native_acquisition(self):
    """The original acquisition failures preserve their source disposition."""
    try:
        yield
    except (OSError, TimeoutError, SelectedToolDenied) as error:
        failure = NativePiUnavailable(f'Native resource acquisition failed: {type(error).__name__}: {error}')
        failure.__cause__ = error
        self.prompt_state.raise_native_failure(failure, self.launch.session.attestation())
    except NativePiUnavailable as error:
        self.prompt_state.raise_native_failure(error, self.launch.session.attestation())

async def receive_record(self) -> AsyncIterator[events.AgentEvent]:
    while self.rejected_commands:
        yield self.rejected_commands.pop(0)
    self.rejected_signal.clear()
    try:
        self.line = await self.watchdog.read(self)
    except TurnWaitExpired as expired:
        async for event in expired.wait.expire(self):
            yield event
        return
    if not self.line:
        if self.awaiting_native_attestation:
            self.output.preflight_failure = FailureReason.PREFLIGHT_EXIT
            self.output.diagnostic = {'elapsed_ms': round((self.loop.time() - self.watchdog.launch_started_at) * 1000), 'spawn_ms': self.watchdog.spawn_ms}
            if self.watchdog.session_bytes is not None:
                self.output.diagnostic['session_bytes'] = self.watchdog.session_bytes
            self.output.record_failure(failures.InputIdUnavailable('Pi native input-ID capability preflight ended before attestation.'))
        self.finished = True
        return
    self.line = self.line.strip()
    if not self.line:
        self.skip = True
        return
    try:
        self.payload = PiRpcChannel.decode_record(self.line)
    except json.JSONDecodeError:
        self.skip = True
        return
    except (ValueError, TypeError) as error:
        if self.awaiting_native_attestation:
            self.output.record_failure(failures.InputIdUnavailable(f'Invalid Pi capability preflight response: {error}'))
            await self.native.shutdown()
            self.finished = True
            return
        raise

def request_retried(self) -> None:
    """Pi compacted after an overflow and re-sends the same request."""
    self.output.request_retried()

async def retain_or_close(self) -> AsyncIterator[events.AgentEvent]:
    await self.native.finish_input()
    identity = self.native.attestation.identity
    if self.persistent_session is not None and self.require_input_id and (identity is not None) and self.prompt_state.permits_retention(self):
        self.native.sensitive_diagnostics = self.output.sensitive
        self.native_session.retain(self.native, identity)
    if not self.native_session.custody.retained:
        outcome = await self.native.shutdown(graceful=True)
        if isinstance(outcome, TimedOutOutcome):
            self.output.record_failure(failures.BackendDidNotExit('agent backend did not exit'))
    if False:
        yield

async def finish_result(self) -> AsyncIterator[events.AgentEvent]:
    for event in self.output.done(self, self.error_text):
        yield event

def __post_init__(self) -> None:
    if any((not row.exists or key != row.key for key, row in self.rows.items())):
        raise ValueError('Input document key differs from its attempt')

def record(self, *originals: ReservedInput) -> InputDocument:
    """An existing original cannot be replaced by another reservation."""
    additions = {}
    for row in originals:
        if row.key not in self.rows:
            additions.setdefault(row.key, row)
    return replace(self, rows={**self.rows, **additions}) if additions else self

def originals(self, keys: tuple[str, ...]) -> tuple[StoredInput, ...]:
    """Capture ordered originals from their sole durable declaration owner."""
    if len(set(keys)) != len(keys):
        raise ValueError('Original input membership contains duplicate keys')
    try:
        return tuple((self.rows[key] for key in keys))
    except KeyError as error:
        raise ValueError('Original input receipt is unavailable') from error

def transition(self, keys: tuple[str, ...], change) -> InputDocument:
    """Each original state decides its successor; unchanged rows stay intact."""
    successors = {key: successor for key in keys if (successor := change(self.lookup(key))) is not None}
    return replace(self, rows={**self.rows, **successors}) if successors else self

def shared_state(self, keys: tuple[str, ...]) -> type[InputAttempt] | None:
    """Project only a complete, homogeneous durable observation."""
    states = {type(self.lookup(key)) for key in keys}
    if len(states) == 1 and all((self.lookup(key).exists for key in keys)):
        return states.pop()
    return None

def answered_by(self, lease, source, snapshot, target: str) -> tuple[MessageReference, ...]:
    """The bus messages the lease's turn took in that a message to target answers."""
    delivered = tuple((reference for row in sorted(self.rows.values(), key=lambda item: item.order) if (reference := row.delivered_in(lease, source.marker.root_id, snapshot)) is not None))
    route = target if is_channel_target(target) else snapshot.canonical_name(target)
    return tuple((original.message.reference for original in source.references(delivered) if original.message.exact_reply_target == route))

def unbound_wire_inputs(self, root_id: str) -> dict[MessageReference, StoredInput]:
    """Original bus deliveries with positive evidence that Pi never received them."""
    return {reference: row for row in self.rows.values() if (reference := row.unbound_delivery(root_id)) is not None}

def delivery_overview(self, owners: frozenset[str], *, include_history: bool=False, awaiting_keys: frozenset[str] | None=None) -> dict:
    current, historical = ([], [])
    dismissed = historical_count = 0
    for row in self.unknown(owners):
        if row.historical_notice(awaiting_keys):
            dismissed += int(row.notice_dismissed)
            historical_count += int(not row.notice_dismissed)
            if include_history:
                historical.append({**row.public(), 'noticeDismissed': row.notice_dismissed})
        else:
            current.append(row.public())
    return {'inputs': current, 'historicalCount': historical_count, 'dismissedHistoricalCount': dismissed, 'historicalInputs': historical, 'currentScope': 'owner_queue' if awaiting_keys is not None else 'unobserved'}

def _unresolved_kinds() -> str:
    """The unresolved members' stored names, derived from their declarations."""
    return '(' + ', '.join((sql_literal(member) for member in InputAttempt.members_with(StoredInput) if member.unresolved)) + ')'

def _members(column: str, values) -> tuple[str, tuple]:
    values = tuple(values)
    return (f'''"{column}" IN ({', '.join(('?' for _ in values))})''', values)

@staticmethod
def _document(connection: sqlite3.Connection, where: str, parameters: tuple) -> InputDocument:
    return InputDocument({row.key: row.attempt for row in InputDispositionRow.select(connection, where=where, parameters=parameters)})

def _select(self, where: str, parameters: tuple=()) -> InputDocument:
    if not self.path.exists():
        return InputDocument({})
    with self.snapshot() as connection:
        return self._document(connection, where, parameters)

def _update(self, where: str, parameters: tuple, change) -> InputDocument:
    """Change only the selected rows; the callback returns the original to skip writing."""
    with self.writing() as connection:
        original = self._document(connection, where, parameters)
        changed = change(original)
        for key, row in changed.rows.items():
            if original.rows.get(key) is not row:
                InputDispositionRow(key, row).upsert(connection)
        return changed

def unresolved(self, owners: frozenset[str]) -> InputDocument:
    where, parameters = _members('owner', sorted(owners))
    return self._select(f'unresolved = 1 AND {where}', parameters)

@staticmethod
def bus_key(message: Message, owner: Thread) -> str:
    return message.response_policy.disposition_key(message, owner)

def record_originals(self, *originals: ReservedInput, custody: ExitStack | None=None) -> InputDocument:
    """Publish one original cohort; return its exact captured document."""

    def reserve(original: InputDocument) -> InputDocument:
        changed = original.record(*originals)
        if changed is not original and custody is not None:
            custody.callback(self.settle_unbound, tuple((key for key in changed.rows if key not in original.rows)))
        return changed
    return self._update(*_members('key', (row.key for row in originals)), reserve)

def reserve(original: InputDocument) -> InputDocument:
    changed = original.record(*originals)
    if changed is not original and custody is not None:
        custody.callback(self.settle_unbound, tuple((key for key in changed.rows if key not in original.rows)))
    return changed

def reserve_turn(self, owner: str, turn: TurnId, admission: int, text: str, *, custody: ExitStack) -> SingleInputBatch:
    """Enlist rollback before publication; caller retains the original wire scope."""
    from .channel_input_batch import SingleInputBatch
    row = ReservedInput(f'turn:{turn.value}', None, owner, admission, owner, text)
    document = self.reserve_originals(row, custody=custody)
    return SingleInputBatch(document.originals((row.key,)))

def reserve_originals(self, *originals: ReservedInput, custody: ExitStack) -> InputDocument:
    """Require fresh originals, retaining the exact publication and rollback."""
    document = self.record_originals(*originals, custody=custody)
    if any((document.rows[row.key] is not row for row in originals)):
        raise RelationViolationError('Input reservation already exists')
    return document

def bind_turn_input(self, keys: tuple[str, ...], *, admission: int, turn_id: str, native_id: str, text: str, already_bound: bool) -> bool:
    """Bind a turn's unresolved inputs to the native input carrying them.

        ``already_bound`` (a send-now re-send) requires the existing binding to match.
        """
    document = self.read(keys)
    for row in document.rows.values():
        row.require_not_cleared()
    if any((not document.lookup(key).unresolved or not document.lookup(key).matches_admission(admission) for key in keys)):
        return False
    if already_bound:
        return all((document.lookup(key).matches_native(native_id=native_id, turn_id=turn_id, text=text) for key in keys))
    return self.bind_originals(keys, admission=admission, turn_id=turn_id, native_id=native_id, text=text)

def bind_originals(self, keys: tuple[str, ...], *, admission: int, turn_id: str, native_id: str, text: str) -> bool:
    """Bind the complete captured original atomically; no partial batch grant."""
    bound = False

    def change(document: InputDocument) -> InputDocument:
        nonlocal bound
        if not keys or len(set(keys)) != len(keys):
            return document
        successors = tuple((document.lookup(key).bind(admission=admission, turn_id=turn_id, native_id=native_id, text=text) for key in keys))
        if any((row is None for row in successors)):
            return document
        bound = True
        return replace(document, rows={**document.rows, **dict(zip(keys, successors, strict=True))})
    self._update(*_members('key', keys), change)
    return bound

def change(document: InputDocument) -> InputDocument:
    nonlocal bound
    if not keys or len(set(keys)) != len(keys):
        return document
    successors = tuple((document.lookup(key).bind(admission=admission, turn_id=turn_id, native_id=native_id, text=text) for key in keys))
    if any((row is None for row in successors)):
        return document
    bound = True
    return replace(document, rows={**document.rows, **dict(zip(keys, successors, strict=True))})

def settle_unbound(self, keys: tuple[str, ...]) -> InputDocument:
    """Publish one complete retirement and return that exact document cut."""
    return self._update(*_members('key', keys), lambda document: document.settle_unbound(keys))

def review_for_goal(self, keys: tuple[str, ...], *, owners: frozenset[str], goal_id: str, goal_revision: int, turn_id: str, observed: tuple[InputAttempt, ...]=()) -> None:
    decision = GoalInputDecision(goal_revision, turn_id)

    def review(document: InputDocument) -> InputDocument:
        rows = dict(document.rows)
        for row in observed:
            if row.key not in keys or (row.key in rows and rows[row.key] != row):
                raise ValueError('Reviewed inputs changed; inspect them again.')
            rows.setdefault(row.key, row)
        if any((key not in rows or rows[key].owner not in owners or (not rows[key].unresolved) for key in keys)):
            raise ValueError('Reviewed inputs changed; inspect them again.')
        if not keys:
            return document
        return replace(document, rows={**rows, **{key: rows[key].review(goal_id, decision) for key in keys}})
    self._update(*_members('key', keys), review)

def review(document: InputDocument) -> InputDocument:
    rows = dict(document.rows)
    for row in observed:
        if row.key not in keys or (row.key in rows and rows[row.key] != row):
            raise ValueError('Reviewed inputs changed; inspect them again.')
        rows.setdefault(row.key, row)
    if any((key not in rows or rows[key].owner not in owners or (not rows[key].unresolved) for key in keys)):
        raise ValueError('Reviewed inputs changed; inspect them again.')
    if not keys:
        return document
    return replace(document, rows={**rows, **{key: rows[key].review(goal_id, decision) for key in keys}})

def dismiss_historical(self, owners: frozenset[str], *, awaiting_keys: frozenset[str] | None=None) -> dict:

    def dismiss(document: InputDocument) -> InputDocument:
        changed = {row.key: replace(row, notice_dismissed=True) for row in document.unknown(owners) if row.historical_notice(awaiting_keys) and (not row.notice_dismissed)}
        return replace(document, rows={**document.rows, **changed}) if changed else document
    where, parameters = _members('owner', sorted(owners))
    return self._update(f'unresolved = 1 AND {where}', parameters, dismiss).delivery_overview(owners, awaiting_keys=awaiting_keys)

def dismiss(document: InputDocument) -> InputDocument:
    changed = {row.key: replace(row, notice_dismissed=True) for row in document.unknown(owners) if row.historical_notice(awaiting_keys) and (not row.notice_dismissed)}
    return replace(document, rows={**document.rows, **changed}) if changed else document

def __init__(self, wait: TurnWait, message: str):
    super().__init__(message)
    self.wait = wait

def __init__(self, budget: float=0.0):
    self.budget = budget
    self.elapsed = 0.0

@contextmanager
def charge(self, clock: Callable[[], float]):
    started_at = clock()
    remaining = max(0.0, self.budget - self.elapsed)
    try:
        yield
    finally:
        self.elapsed += min(remaining, max(0.0, clock() - started_at))

@contextmanager
def charge(self, clock: Callable[[], float]):
    yield

def compacted(self, input_started: bool) -> None:
    if not input_started:
        self.input_wait.restart()

async def observe(self, event: PiEvent, session: TurnSession) -> AsyncIterator[events.AgentEvent]:
    self.tick()
    if self.retry_recovery_pending and event.retry_progress:
        self.retry_recovery_pending = False
        yield self.state('recovered', self.retry_recovery_reason, 0, phase=phases.ModelWaitPhase())
    if event.accepts_prompt:
        self.prompt_accepted = True
        if event.invalidates_stop:
            session.output.final_assistant_stop = False
        self.progress()
        if not session.active_tools:
            self.phase = self.phase.model_progress()

def wait_for(self, session: TurnSession) -> TurnWait:
    if session.awaiting_native_attestation:
        return self.preflight_wait
    if session.stats.requested:
        return self.poll_wait
    if session.prompt_state.awaiting_start and (not self.phase.pauses_input_clock):
        return self.input_wait
    if session.active_tools:
        return self.unbounded_wait
    if self.phase.model_wait(self.model_wait.timeout()) is None:
        return self.unbounded_wait
    return self.model_wait

async def read(self, session: TurnSession) -> bytes:
    if session.rejected_signal.is_set():
        return b'\n'
    read_task = asyncio.create_task(session.native.reader.readline())
    reject_task = asyncio.create_task(session.rejected_signal.wait())
    finish_task = asyncio.create_task(session.finish_event.wait()) if session.finish_event is not None and (not session.stats.requested) else None
    tasks = {read_task, reject_task}
    if finish_task is not None:
        tasks.add(finish_task)
    forwarding = session.native.forwarding_task
    observed = tasks | {forwarding} if forwarding is not None else tasks
    wait = self.wait_for(session)
    try:
        with wait.charge(self.clock):
            done, _ = await asyncio.wait(observed, timeout=wait.timeout(), return_when=asyncio.FIRST_COMPLETED)
        if not done:
            await asyncio.sleep(0)
            done = {task for task in observed if task.done()}
        if not done:
            raise wait.expired(session)
        if forwarding is not None and forwarding in done:
            await session.native.shutdown()
            if not forwarding.cancelled():
                forwarding.result()
            return b''
        if read_task in done:
            return read_task.result()
        if finish_task is not None and finish_task in done:
            read_task.cancel()
            await asyncio.gather(read_task, return_exceptions=True)
            if session.awaiting_native_attestation:
                return b''
            await session.stats.request(session)
        return b'\n'
    finally:
        for pending in tasks:
            if not pending.done():
                pending.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)

@classmethod
def capture(cls, snapshot: RegistrySnapshot, name: str):
    owner = snapshot.require_active(name)
    return cls(snapshot.owner_identity(owner.name), owner.require_process(), snapshot.admission_generations[owner.name])

@property
def name(self) -> str:
    return self.identity.incarnation.name

def require_current(self, snapshot: RegistrySnapshot) -> Thread:
    try:
        snapshot.require_owner_process(self.identity, self.process)
    except RelationViolationError as error:
        raise OwnerSelectionChangedRefusal() from error
    if snapshot.admission_generations[self.name] != self.admission_generation:
        raise OwnerGenerationChangedRefusal()
    return snapshot.require_active(self.name)

def __post_init__(self) -> None:
    if self.before <= 0 or self.after <= self.before:
        raise ValueError('Owner release requires an advanced admission and a closed turn')
    self.thread.require_idle()

def current(self, snapshot: RegistrySnapshot, expected: Thread, admission: int) -> bool:
    """The stored release proves this retired owner, never a replacement."""
    if self.before != admission or self.thread.incarnation != expected.incarnation:
        return False
    if self.thread.process_identity != expected.process_identity:
        return False
    if self.after != snapshot.admission_generations.get(self.thread.name):
        return False
    if self.thread != snapshot.threads.get(self.thread.name):
        return False
    return snapshot.statuses[self.thread.name].stopped

@property
def record_type(self):
    return dict[str, OwnerReleaseReceipt]

def remove_threads(self, threads: Sequence[Thread]) -> None:
    """A receipt attests one declared owner; it ends with the declaration."""
    names = {thread.name for thread in threads}
    self.update(lambda receipts: {name: receipt for name, receipt in receipts.items() if name not in names} if names & receipts.keys() else receipts)

def require_restart_idle(self, thread: Thread) -> None:
    """Do not interrupt a live turn; an old attempt settles after owner release."""
    from .restart_refusals import OwnerBusyRefusal
    try:
        thread.require_idle()
    except RelationViolationError as error:
        raise OwnerBusyRefusal() from error

def ensure_owner(self, name: str, *, agent_bin: str=NativeArguments.default_binary, agent_args: Sequence[str] | None=None) -> Thread:
    with _store_lock(self._wire_lock_path):
        self.maintenance.assert_open_unlocked()
        thread = self.registry.require(name)
        thread.execution.require_native()
        if not thread.role.executable or not self.registry.status(thread.name).active:
            raise RelationViolationError('Explicit start is required for a stopped agent.')
        return thread if thread.process_alive else self._launch_owner_unlocked(thread, agent_bin, agent_args, launch_runtime=LaunchRuntime.current())

def start(self, name: str, *, agent_bin: str | None=None, agent_args: Sequence[str] | None=None) -> OwnerStartResult:
    with _store_lock(self._wire_lock_path):
        self.maintenance.assert_open_unlocked()
        thread = self.registry.require(name)
        thread.execution.require_native()
        status = self.registry.status(thread.name)
        if not thread.role.executable or not status.visible:
            raise RelationViolationError('Only visible agent threads can be started.')
        if thread.process_alive:
            if not status.active:
                raise RelationViolationError('Stopped owner has not exited yet.')
            return OwnerStartResult(thread.name, thread.pid, False)
        owner = self._launch_owner_unlocked(thread, NativeArguments.configured_binary(agent_bin), agent_args, launch_runtime=LaunchRuntime.current())
        return OwnerStartResult(owner.name, owner.pid, True)

def restart_entrypoint(self, source_binary: str, runtime: LaunchRuntime) -> str:
    """Choose this runtime's reviewed native entrypoint for a private handoff."""
    if self._private_nk_launch is None:
        return source_binary
    self._private_nk_launch.validate()
    return runtime.native_entrypoint

@contextmanager
def _signal_guard(self, thread: Thread, admission_generation: int):
    with _store_lock(self._wire_lock_path):
        self._require_same_stop_owner(thread, admission_generation)
        yield

def stop(self, name: str) -> None:
    with _store_lock(self._wire_lock_path):
        snapshot = self.registry.snapshot()
        thread = self.registry.require(name)
        if not snapshot.statuses[thread.name].active and (thread.process_identity is None or thread.pid == os.getpid()):
            return
        if snapshot.statuses[thread.name].active and thread.pid == os.getpid():
            if RestartEnvironment.called_by(thread.name, canonicalize=lambda caller: self.registry.require(caller).name):
                self._release_current_owner_unlocked(thread.name)
            else:
                self.registry.unregister(thread.name)
            return
        generation = snapshot.admission_generations[thread.name]
    if thread.process_alive:
        self._stop_process(thread, generation)
    self._finish_stopped_owner(thread, generation)
    from .attempt_recovery import RecoveryMonitorCapability
    RecoveryMonitorCapability.settle_stopped_owner(self.root, thread)

def require_launch_authority(self) -> PrivateNkLaunch | None:
    """Check this lifecycle's launch authority without reserving a process.

        Callers hold the wire lock. A preserving restart can check before
        fencing; every actual launch rechecks the same owner after cutover.
        """
    private_launch = self._private_nk_launch
    if private_launch is None:
        if self.bus.log.read_metadata_unlocked().private:
            raise PublicationActivationBlocked('private owner launch requires explicit matching root and package')
    else:
        private_launch.validate()
    return private_launch

def _launch_owner_unlocked(self, thread: Thread, agent_bin: str, agent_args: Sequence[str] | None=None, *, launch_runtime: LaunchRuntime, startup_input_key: str | None=None, environment: Mapping[str, str] | None=None) -> Thread:
    self.maintenance.assert_open_unlocked()
    env = dict(os.environ if environment is None else environment)
    launch_runtime.require_available()
    env = launch_runtime.environment(env)
    for key in ('PI_PROMPT', 'PI_PARENT_ID', 'PI_TASK', 'AGENT_COMMS_STARTUP_INPUT_KEY', ROOT_ID_ENV, PACKAGE_ENV):
        env.pop(key, None)
    private_launch = self.require_launch_authority()
    if private_launch is not None:
        if agent_bin == 'pi':
            agent_bin = launch_runtime.native_entrypoint
        else:
            agent_bin = str(Path(shutil.which(agent_bin) or agent_bin).resolve(strict=True))
        from .coordinator import Coordination
        with Coordination(str(self.root / 'coordination.sqlite3')) as store:
            store.install_private_runtime()
            store.participants.register(thread.incarnation.lookup, thread.name, thread.name, committed=True)
    env.update({RestartEnvironment.owner_key: thread.name, 'PI_AGENT_TAGS': ','.join(sorted(thread.tags)), 'AGENT_COMMS_TAGS': ','.join(sorted(thread.tags)), 'PI_WORKTREE': thread.worktree, NativeArguments.binary_key: agent_bin})
    if private_launch is not None:
        private_launch.apply_environment(env)
    else:
        env['AGENT_COMMS_ROOT'] = str(self.root.resolve())
    if thread.parent is not None:
        env['PI_PARENT_ID'] = thread.parent
    if thread.task is not None:
        env['PI_TASK'] = thread.task
    if startup_input_key is not None:
        env['AGENT_COMMS_STARTUP_INPUT_KEY'] = startup_input_key
    if agent_args is not None:
        env[NativeArguments.arguments_key] = shlex.join(agent_args)
    owned: Thread | None = None

    def reserve(identity: ProcessIdentity) -> None:
        nonlocal owned
        owned = replace(thread, process_identity=identity, active_turn=None)
        self.registry.register(owned, new_owner=True)
    with owner_process_output(self.root, thread) as output:
        ParentedProcess.launch((str(launch_runtime.interpreter), '-m', 'agent_comms.worker'), env=env, cwd=thread.worktree, output=output, before_start=reserve)
    assert owned is not None
    return owned

def _require_same_stop_owner(self, thread: Thread, admission_generation: int) -> None:
    snapshot = self.registry.snapshot()
    if self._released_same_owner(snapshot, thread, admission_generation):
        return
    try:
        snapshot.require_stopping_owner(thread, admission_generation)
    except RelationViolationError as error:
        raise RelationViolationError(f'Owner changed while stopping {thread.name!r}; refusing a stale signal.') from error

def _released_same_owner(self, snapshot: RegistrySnapshot, thread: Thread, admission_generation: int) -> bool:
    receipt = self.releases.read().get(thread.name)
    return receipt.current(snapshot, thread, admission_generation) if receipt is not None else False

async def finish_result(self) -> AsyncIterator[events.AgentEvent]:
    if not self.native_session.custody.retained:
        self.prompt_state.raise_native_failure(NativePiUnavailable(self.output.failure_text or 'Native session preparation failed'), self.native.attestation)
    if False:
        yield

