def publish_success(self) -> None:
    """Join each acquired original send before releasing the turn lease."""
    published: list[MessageReference] = []

    def record_publication() -> None:
        self.comms.transcripts.record_turn_publication(lease=self.turn_lease, checkpoint=self.checkpoint, routing=self.routing, published=tuple(published))
    with ExitStack() as publications:
        publications.callback(record_publication)
        if self.reply_parts:
            for target in self.reply_targets:
                message = self.comms.messaging.send_message(self.thread_name, target, ''.join(self.reply_parts))
                published.append(message.reference)

def publish_checkpoint(self):
    """Close terminal publication and its original read before ACP delivery."""
    if self.result is not None and self.result.ok:
        self.publish_success()
    else:
        diagnostic_path = record_terminal_failure(self.comms.root, turn_id=self.turn_lease.turn_id, thread=self.thread_name, event=asdict(self.result) if self.result is not None else {}, sequences=tuple((origin.seq for origin in self.origins)))
        notice_targets = tuple(dict.fromkeys((*self.reply_targets,) + tuple((origin.target if is_channel_target(origin.target) else origin.sender for origin in self.origins if origin.sender != self.thread_name))))
        for target in notice_targets:
            prefix = 'Request failed' if target in self.reply_targets else 'Delivery failed'
            self.comms.messaging.send(self.thread_name, target, f'{prefix}: backend turn did not complete. [Open diagnostic]({diagnostic_path.as_uri()})', AlertKind, notice=True)
    return self.comms.transcripts.transcript_checkpoint(self.thread_name)

