def accept(self, event: PiEvent) -> NativeAttestation:
    if not event.responds_to(self.request):
        return self
    if event.success is not True:
        raise AttestationError(failures.InputIdUnavailable('Pi native input-ID capability preflight failed.'))
    try:
        data = event.data.require_payload()
    except ValueError as error:
        raise AttestationError(failures.InputIdUnavailable('Pi native input-ID capability preflight failed.')) from error
    if data.native_input_proof_capability != CAPABILITY:
        raise AttestationError(failures.InputIdUnavailable('Pi native input-ID capability preflight failed.'))
    observed = ObservedAttestation(data)
    if self.expected is not None and observed.identity != self.expected:
        raise IdentityAttestationError(failures.IdentityUncertain('Pi session identity changed during this turn.'))
    return observed

@property
