    return identity

@property
def recipient_lookup(self) -> str:
    """All original sources belong to the same admitted participant."""
    lookups = {row.recipient_lookup for row in self.assignments}
    if len(lookups) != 1:
        raise IdentityConflict('Native batch requires one original participant')
    return next(iter(lookups))

@property
@abstractmethod
def execution(self) -> NativeInputExecution:
    ...

@abstractmethod
def require_phase(self, store: Coordination, current: WakeAssignment) -> None:
    ...

@abstractmethod
def reserve_claim(self, store: Coordination, db: sqlite3.Connection) -> None:
    """Fence this stage and reject any previous dispatch before inserting an ID."""

def verify(self, store: Coordination, owner: ParticipantOwner, input_id: str, token_digest: str, context: NativeContextProof, *, wire_root_id: str, prompt: str) -> None:
    with NativeEntry.open_input_evidence(context.session_file) as evidence:
        if not context.corroborates_input(input_id, evidence=evidence):
            raise IdentityConflict('Pi live assembled context differs from its reserved input proof')
        with self.bound_prompt(store, input_id, owner, wire_root_id, prompt, blocking=True) as binding:
            if not expected_prompt_matches_journal(context.session_file, binding, evidence=evidence):
                raise IdentityConflict('live native input lacks exact bound source prompt equality')
            with store.session.read():
                original = self.pending_input(store, input_id, owner, token_digest)
                original.require_session_identity().require_context(context)

def require_claim(self, store: Coordination) -> None:
    for captured in self.assignments:
        current = store.assignments.get(captured.assignment_id)
        try:
            NativeClaimCheck(captured=captured, current=current).require_valid()
        except ReservationViolationError as error:
            raise StaleFence(f'selected claim identity changed before native send: {error}') from error
        self.require_phase(store, current)

def require_reservation(self, db: sqlite3.Connection, input_id: str, owner: ParticipantOwner, token_digest: str) -> NativeRuntimeInput:
    reserved = NativeRuntimeInput.one(db, input_id=input_id)
    if reserved is None:
        raise StaleFence('native reservation missing before send')
    self.require_sources(db, input_id)
    try:
        NativeReservationCheck(row=reserved, stage=self, owner=owner.coordinator_identity(self.recipient_lookup), token_digest=token_digest).require_valid()
    except ReservationViolationError as error:
        raise StaleFence(f'native reservation changed before send: {error}') from error
    return reserved

def require_sources(self, db, input_id) -> None:
    if self.execution.source_assignment_ids(db, input_id) != tuple((row.assignment_id for row in self.assignments)):
        raise IdentityConflict('Native input changed its original source membership')

@contextmanager
def bound_prompt(self, store: Coordination, input_id: str, owner: ParticipantOwner, wire_root_id: str, prompt: str, *, blocking: bool=False) -> Iterator[PromptBinding]:
    with expected_prompt_binding(store, input_id, blocking=blocking) as binding:
        self.require_bound_prompt(binding, owner, wire_root_id, prompt)
        yield binding

def require_bound_prompt(self, binding: PromptBinding | None, owner: ParticipantOwner, wire_root_id: str, prompt: str) -> None:
    if binding is None:
        raise IdentityConflict('native send has no durable prompt binding')
    try:
        NativeBindingCheck(row=binding, stage=self, owner=owner.coordinator_identity(self.recipient_lookup), wire_root_id=wire_root_id, prompt_digest=TextDigest(native_request_digest(prompt))).require_valid()
    except ReservationViolationError as error:
        raise IdentityConflict(f'native send differs from its durable prompt binding: {error}') from error

def fail_claims(self, store: Coordination, db: sqlite3.Connection) -> tuple[WakeAssignment, ...]:
    """Move this triage's deferred claims to Failed inside the caller's transaction."""
    for captured in self.assignments:
        current = store.assignments.get(captured.assignment_id)
        if current.lifecycle != DeferredAssignment.build(current.lifecycle.mode, None, None):
            raise StaleFence('failed triage claim is no longer deferred')
        updated = WakeAssignment.update(db, where='assignment_id=? AND revision=?', parameters=(current.assignment_id, current.revision), lifecycle=current.lifecycle.preengagement(FailedAssignment), revision=current.revision + 1, updated_at_ms=store.session.now(current.updated_at_ms))
        if updated.rowcount != 1:
            raise StaleFence('failed triage lost an original batch claim')
    return tuple((store.assignments.get(captured.assignment_id) for captured in self.assignments))

@property
def execution(self) -> TriageNativeExecution:
    return TriageNativeExecution()

def reserve_claim(self, store: Coordination, db: sqlite3.Connection) -> None:
    for captured in self.assignments:
        current = store.assignments.get(captured.assignment_id)
        if current != captured or not current.lifecycle.triage_pending:
            raise IdentityConflict('triage claim changed before native batch reservation')
        if SqlValue.for_annotation(int).read(db.execute(f'SELECT 1 FROM ({self.execution.source_membership_sql()}) members WHERE members.assignment_id=? LIMIT 1', (captured.assignment_id,))):
            raise IdentityConflict('triage source was previously reserved; no retry')
        update = WakeAssignment.update(db, where="assignment_id=? AND revision=? AND disposition='triage_pending'", parameters=(current.assignment_id, current.revision), lifecycle=DeferredAssignment.build(current.lifecycle.mode, None, None), revision=current.revision + 1, updated_at_ms=store.session.now(current.updated_at_ms))
        if update.rowcount != 1:
            raise IdentityConflict('triage batch reservation lost an original claim CAS')

def commit(self, store: Coordination, owner: ParticipantOwner, input_id: str, token_digest: str, context: NativeContextProof, decision: SelectedTriage) -> tuple[WakeAssignment, ...]:
    with store.session.transaction() as db:
        row = self.pending_input(store, input_id, owner, token_digest)
        self.require_claim(store)
        row.commit_context(db, context, verdict=type(decision))
        for captured in self.assignments:
            decision.settle(store, db, store.assignments.get(captured.assignment_id))
        return tuple((store.assignments.get(captured.assignment_id) for captured in self.assignments))

def require_phase(self, store: Coordination, current: WakeAssignment) -> None:
    if current.lifecycle != DeferredAssignment.build(current.lifecycle.mode, None, None) or current.revision != next((row.revision for row in self.assignments if row.assignment_id == current.assignment_id)) + 1:
        raise StaleFence('triage claim changed before native send')

