def main(argv: Sequence[str] | None=None) -> int:
    try:
        with ExitStack() as route_guard:
            args = build_parser().parse_args(argv)
            command = CliCommand.from_namespace(args)
            from .active_route import resolve_comms_route
            route = resolve_comms_route(Path(args.root).expanduser() if args.root else None)
            route_guard.enter_context(route.admit_client())
            comms = wire(route)
            return command.run(comms, sys.stdout)
    except KeyboardInterrupt:
        return 130
    except StoppedOwnerFailure as exc:
        exc.abandon()
        return _fail(exc)
    except Exception as exc:
        return _fail(exc)
    return 0

def forward(self, after: int, through: int):
    with self.path.open('rb') as stream:
        stream.seek(after)
        while stream.tell() < through:
            start = stream.tell()
            raw = stream.readline(through - start)
            if not raw:
                return
            yield NativeRecord.read(start, stream.tell(), raw)

