def schedule(self) -> None:
    try:
        self.require_valid()
    except ReservationViolationError:
        return
    self.inputs.register_wake(self.session_id, self.inputs.runtime.background(self.run()))

async def run(self) -> None:
    inputs, session_id = (self.inputs, self.session_id)
    while inputs.pending_turns.get(session_id):
        if ClosingScheduleRule().violated(self):
            return
        async with inputs.effects.turns.turn_locks.setdefault(session_id, asyncio.Lock()):
            hold = await Coordination.run_worker(inputs.comms.owners.maintenance.read)
            if hold.turn_pending:
                return hold
            snapshot = await Coordination.run_worker(inputs.comms.registry.snapshot)
            owner = snapshot.require(inputs.sessions.require(session_id))
            try:
                snapshot.status(owner.name).require_running()
            except RelationViolationError:
                inputs.pending_turns.pop(session_id, None)
                continue
            pending = inputs.pending_turns.pop(session_id, [])
            goal = owner.active_goal
            if goal is not None:
                pending = [turn for turn in pending if turn.goal_id == goal.id]
            if not pending:
                continue
            pending, remaining = ScheduledTurn.take_batch(pending)
            if remaining:
                inputs.pending_turns[session_id] = remaining
            inputs.effects.turns.turn_tasks[session_id] = asyncio.current_task()
            try:
                await inputs.effects.turns.run_agent_turn(session_id, inputs.sessions.require(session_id), '\n\n'.join((turn.prompt for turn in pending)), origins=tuple((origin for turn in pending for origin in turn.origins)), autonomous_goal=len(pending) == 1 and pending[0].autonomous_goal, dependency_wait_id=pending[0].goal_wait_id)
            except RequestError as error:
                if goal is None:
                    raise
                pending[0].require_dependency_wake(error)
                await Coordination.run_worker(partial(inputs.comms.goals.block_goal_after_failed_turn, owner.name, started_goal=goal, expected_worktree=owner.worktree, diagnostic='Standby wake launch authority unavailable; inspect the UNKNOWN input before explicit Retry. No input was replayed.'))
                await inputs.effects.turns.goals.sync_goal_execution(session_id, owner.name)
            finally:
                inputs.effects.turns.turn_tasks.pop(session_id, None)

