    decorator = function.decorator_list[0]
    if not (isinstance(decorator, ast.Name) and decorator.id in properties or (isinstance(decorator, ast.Attribute) and decorator.attr == 'property' and isinstance(decorator.value, ast.Name) and (decorator.value.id in builtins))):
